  }
}'

export GROK2API_API_KEY="g2a_your_api_key"

curl -X POST "http://127.0.0.1:8000/v1/tts" \
  -H "Authorization: Bearer $GROK2API_API_KEY" \
  -H "Content-Type: application/json" \
  -d '{
  "model": "grok-voice-latest",
  "text": "Hello from Grok voice.",
  "voice_id": "eve",
  "language": "en",
  "output_format": {
    "codec": "mp3"
  }
}'

